package main

import (
	"fmt"
	"time"
)

// Fungsi worker yang mengirim data via channel
func producer(ch chan string) {
	fmt.Println("[Producer] Mulai menyiapkan pesanan...")
	time.Sleep(2 * time.Second) // Simulasi kerja keras 2 detik

	// Mengirim data ke dalam channel
	fmt.Println("[Producer] MENGIRIM pesanan ke kurir!")
	ch <- "Kopi Espresso" 
}

func main() {
	fmt.Println("=== Membuka Kedai Kopi ===")

	// 1. Buat channel (pipa transfer)
	kurir := make(chan string)

	// 2. Jalankan barista di background
	go producer(kurir)

	fmt.Println("[Main] Menunggu pesanan dari barista...")

	// 3. Program Utama akan MEMBEKU (block) di baris ini
	// sampai channel 'kurir' kemasukan data.
	pesanan := <-kurir

	fmt.Println("[Main] MENERIMA pesanan:", pesanan)
	fmt.Println("=== Kedai Tutup ===")
}
